mapper.select:
SELECT q.* FROM question q LEFT JOIN knowledge_point kp ON kp.knowledge_point_id = q.knowledge_point_id 
 AND q.course_code = #{courseCode}
 AND q.lesson_no = #{lessonNo}
 AND q.knowledge_point_id = #{knowledgePointId}
 AND q.type = #{type} AND q.difficulty = #{difficulty}
 AND (q.stem LIKE CONCAT('%', #{keyword}, '%') OR kp.name LIKE CONCAT('%', #{keyword}, '%'))
 ORDER BY q.question_id DESC
